        string P1 = karatsuba.Multiply(Xl, Yl);
        string P2 = karatsuba.Multiply(Xr, Yr);
        string P3 = karatsuba.Multiply(karatsuba.AddStrings(Xl, Xr), karatsuba.AddStrings(Yl, Yr));

